"""Owned finite Windows Selection launch/read/actual AX/close, no uncertain replay."""
from pathlib import Path
import argparse,json,re,uuid,hashlib,base64
from driver import ps,q
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('manifest',type=Path);p.add_argument('action',choices=['launch','read','ax','close','cleanup']);p.add_argument('--label',default='initial');p.add_argument('--resume',choices=['default','bulk','clear','empty'],default='bulk');a=p.parse_args();m=json.loads(a.manifest.read_text());v=json.loads((a.manifest.parent/'windows-stage.json').read_text());assert m['owner']==v['owner']=='preflight'and m['component']==v['component']=='selectionpage'and m['buildExitCode']==0;assert json.loads((r/'docs/replica/ENVIRONMENT_LEASE.json').read_text())['resources']['windows']['owner']=='preflight';o=a.manifest.parent/'actual-windows-input';o.mkdir(exist_ok=True)
base="$app=Join-Path (Join-Path $env:TEMP "+q(v['guestFolder'])+") 'app';"
find=base+"$own=@(Get-Process ReplicaProbe -ErrorAction SilentlyContinue|Where-Object{$_.Path-eq($app+'\\ReplicaProbe.exe')});$w=@($own|Where-Object{$_.MainWindowHandle-ne0}|ForEach-Object{[System.Windows.Automation.AutomationElement]::FromHandle($_.MainWindowHandle)}|Where-Object{$_.Current.Name-eq 'Replica SelectionPage verification'});"
unique="if($w.Count-ne1){throw 'Unique own Selection required'};$w=$w[0];"
if a.action=='launch':
 cases=[c for c in json.loads((r/'docs/replica/source/selectionpage-windows-cases.json').read_text())if c['viewport']==1180 and c['variant']=='default'];assert len(cases)==2;body=json.dumps(cases).encode();name='preflight-selection-input-'+uuid.uuid4().hex+'.json';(r/'artifacts/replica/windows-download'/name).write_bytes(body);extra={'default':'--resume-none','bulk':'--resume-after-bulk','clear':'--resume-after-clear','empty':'--resume-empty'}[a.resume]
 code=find+"if($own.Count){throw 'Own native exists'};Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+name)+" -OutFile ($app+'\\selectionpage-cases.json');if((Get-FileHash ($app+'\\selectionpage-cases.json') -Algorithm SHA256).Hash-ne "+q(hashlib.sha256(body).hexdigest().upper())+"){throw 'Cases hash mismatch'};$proc=Start-Process ($app+'\\ReplicaProbe.exe') -ArgumentList @('--selectionpage-window',($app+'\\selectionpage-cases.json'),$app,"+q(extra)+") -PassThru;$identity=@{pid=$proc.Id;path=($app+'\\ReplicaProbe.exe');started=[DateTime]::UtcNow.ToString('o')};$identity|ConvertTo-Json|Set-Content -Encoding UTF8 ($app+'\\selectionpage-launch.json');$limit=[DateTime]::UtcNow.AddSeconds(10);do{Start-Sleep -Milliseconds 100;"+find+"}while($w.Count-eq0-and [DateTime]::UtcNow-lt $limit);if($w.Count-ne1){throw 'Startup absent; no relaunch'};$identity|ConvertTo-Json;exit 0"
 data=ps(code,timeout=20);json.loads(data);((o/'launch-prior.json').write_bytes((o/'launch.json').read_bytes()) if (o/'launch.json').exists() else None);(o/'launch.json').write_text(data);print(data)
elif a.action=='read':
 data=ps(find+unique+"[Convert]::ToBase64String([IO.File]::ReadAllBytes($app+'\\selectionpage-input.json'));exit 0",retry_read=True);(o/('state-'+a.label+'.json')).write_bytes(base64.b64decode(data));print('Fresh state saved')
elif a.action=='ax':
 code=r'''function Children($walker,$e){$items=[Collections.Generic.List[object]]::new();$seen=[Collections.Generic.HashSet[string]]::new();$c=$walker.GetFirstChild($e);$count=0;while($null-ne$c-and$count++-lt80){if(!$seen.Add(($c.GetRuntimeId()-join','))){break};$items.Add($c);$c=$walker.GetNextSibling($c)};return $items.ToArray()};function Node($walker,$e,$depth){$r=$e.Current.BoundingRectangle;$node=@{id=$e.Current.AutomationId;name=$e.Current.Name;type=$e.Current.ControlType.ProgrammaticName;control=$e.Current.IsControlElement;content=$e.Current.IsContentElement;enabled=$e.Current.IsEnabled;focusable=$e.Current.IsKeyboardFocusable;offscreen=$e.Current.IsOffscreen;box=@{x=$r.X;y=$r.Y;width=$r.Width;height=$r.Height}};if($depth-lt12){$node.children=@(Children $walker $e|ForEach-Object{Node $walker $_ ($depth+1)})};return $node};$views=@();foreach($view in @('Raw','Control')){$walker=if($view-eq'Raw'){[System.Windows.Automation.TreeWalker]::RawViewWalker}else{[System.Windows.Automation.TreeWalker]::ControlViewWalker};$stack=[Collections.Generic.Stack[object]]::new();$stack.Push(@($w,0));$seen=[Collections.Generic.HashSet[string]]::new();$table=$null;$visits=0;while($stack.Count-and$visits++-lt900){$pair=$stack.Pop();$e=$pair[0];$d=[int]$pair[1];if(!$seen.Add(($e.GetRuntimeId()-join','))){continue};if($e.Current.ControlType-eq[System.Windows.Automation.ControlType]::Table){$table=Node $walker $e 0;break};if($d-lt24){foreach($c in(Children $walker $e)){$stack.Push(@($c,($d+1)))}}};if($null-eq$table){throw 'Own table absent'};$views+=@{view=($view+'ViewWalker');visited=$visits;table=$table}};$views|ConvertTo-Json -Depth 20;exit 0'''
 data=ps(find+unique+code,timeout=25,retry_read=True);json.loads(data);(o/('ax-'+a.label+'.json')).write_text(data);print('Actual Raw/Control tree saved')
elif a.action=='close':print(ps(find+unique+"$w.GetCurrentPattern([System.Windows.Automation.WindowPattern]::Pattern).Close();exit 0"))
else:
 data=ps(find+"@{processCount=$own.Count;windowCount=$w.Count}|ConvertTo-Json;exit 0",retry_read=True);c=json.loads(data);assert c['processCount']==c['windowCount']==0;(o/'cleanup.json').write_text(data);print(data)
